import React, { Component } from 'react';
import Loader from "react-loader";

export default class ESign extends Component {
    constructor(props) {
        super(props);
        this.state = {
            url: "",
            aspRespXML: "",
            loaded: true,
            bioMode:false
        };
    }

    componentWillMount() {
        let data = JSON.parse(sessionStorage.getItem("download_data"));
        console.log(data.aspUrl);
        console.log(data.espXML);
        let url = "";
        alert("routing");
        let BIOMODE=false;
        alert(data.bioMode + " - " + data.bioMode);
        if (data.bioMode && data.bioMode === 7) {
            // "apkUrl"
            // url = `https://docuxecstage.finfotech.co.in/apk?msg=${encodeURIComponent(data.espXML)}`;
           
            BIOMODE=true;
            url = data.aspUrl+'?msg=${encodeURIComponent(data.espXML)}'
            window.location.href = url;
        } else {
            url = data.aspUrl;
        }

        this.setState({
            url: url,
            aspRespXML: data.espXML,
            bioMode:BIOMODE
        });
    }

    componentDidMount() {
        if (this.state.bioMode==false) {
            var form = this.refs.form;
            form.submit();
        }

        // Listen for custom URL scheme
        // window.addEventListener("hashchange", this.handleHashChange, false);
    }

    // componentWillUnmount() {
    //     // Clean up the event listener
    //     window.removeEventListener("hashchange", this.handleHashChange, false);
    // }

    // handleHashChange = () => {
    //     const url = new URL(window.location.href);
    //     const result = url.searchParams.get("msg");
    //     if (result) {
    //         console.log("Received response from APK:", result);
    //         this.setState({
    //             loaded: true,
    //             // aspRespXML: result
    //         });
    //     }
    // }

    eSign() {
        this.props.history.push('./dropdoc');
    }

    logout() {
        this.props.history.push('./');
    }

    onLoad() {
        this.setState({ loaded: true });
    }

    render() {
        return (
            <div className="success-container">
                <Loader loaded={this.state.loaded}
                    lines={13} radius={20}
                    corners={1} rotate={0} direction={1} color="#000" speed={1}
                    trail={60} shadow={false} hwaccel={false} className="spinner loader"
                    zIndex={2e9} top="50%" left="50%" scale={1.00}
                    loadedClassName="loadedContent"
                />
                <iframe name="my_iframe" id="my_iframe" frameBorder="0" className="iframe" onLoad={this.onLoad.bind(this)} scrolling="yes"></iframe>
                <form id="URL" name="URL" method="POST" action={this.state.url} encType="multipart/form-data" target="my_iframe" ref="form">
                    <input type="hidden" name="obj" id="obj" value="" />
                    <input type="hidden" name="msg" id="msg" value={this.state.aspRespXML} />
                </form>
            </div>
        );
    }
}
